// The site's content, written by axioma: every page is a JSON file in
// content/pages, every picture's details a JSON file in content/media. The
// schemas are generated by axioma from schema/types at each build.
import { defineCollection } from 'astro:content'
import { glob } from 'astro/loaders'
import { mediaSchema, pageSchema } from '../.axioma/schema'

const pages = defineCollection({
  loader: glob({
    pattern: '*.json',
    base: './content/pages',
    generateId: ({ entry }) => entry.replace(/\.json$/, ''),
  }),
  schema: pageSchema,
})

const media = defineCollection({
  loader: glob({
    pattern: '*.json',
    base: './content/media',
    generateId: ({ entry }) => entry.replace(/\.json$/, ''),
  }),
  schema: mediaSchema,
})

export const collections = { pages, media }
